from .grepper import Grepper, GrepperBehavior
from .journal_reader import JournalReader
from taf.transport.ssh import ssh
from taf.transport.ssh.connection import Connection
try:
    from robot.api import logger as logging
except ImportError:
    import logging


class ssh_addons(object):
    last_grepper_result = None
    last_journalctl_contents = None
    grepper = Grepper()
    journal_reader = JournalReader()
    ssh = ssh()

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def grep_file(self, pattern, file_path, max_count=1, connection=None):
        """Run a grep utility on the remote.

        This runs a 'grep' command on the remote, supplying the pattern and
        file_path attributes "as is" to the command parameters.
        The max_count attribute is the value that will be supplied to the
        '--max-count' option. If max_count is None, the option will not be
        present in the command call.

        The connection parameter references the aliased connection instance
        from taf.transport.ssh that should be used. Refer to it's documentation
        to find out more about the possible values.
        """
        max_count = int(max_count)
        self._log_grepping("Grepping a file:", pattern, file_path, max_count)
        self._set_connection(connection)
        return self._run_grep(pattern, file_path, max_count,
                              GrepperBehavior.BASIC)

    def egrep_file(self, pattern, file_path, max_count=1, connection=None):
        """Run a grep utility on the remote, using regex pattern.

        Same as.grep_file(), except this keyword will run the command with a
        '--extended-regexp' flag.
        """
        max_count = int(max_count)
        self._log_grepping("Egrepping a file (with '--extended-regexp'):",
                           pattern, file_path, max_count)
        self._set_connection(connection)
        return self._run_grep(pattern, file_path, max_count,
                              GrepperBehavior.EXTENDED)

    def fgrep_file(self, pattern, file_path, max_count=1, connection=None):
        """Run a grep utility on the remote, using regex pattern.

        Same as.grep_file(), except this keyword will run the command with a
        '--fixed-strings' flag.
        """
        max_count = int(max_count)
        self._log_grepping("Fgrepping a file (with '--fixed-strings'):",
                           pattern, file_path, max_count)
        self._set_connection(connection)
        return self._run_grep(pattern, file_path, max_count,
                              GrepperBehavior.FIXED)

    def _log_grepping(self, top_line, pattern, file_path, max_count):
        log_msg = ("{}\n\tPattern: {}\n\tFile path: {}\n\t" +
                   "Will stop after: {} occurrence. ")
        log_msg = log_msg.format(top_line, pattern, file_path, max_count)
        logging.info(log_msg)

    def assert_grepper_match(self):
        """Assert, that the last grepping found at least one match."""
        self._check_if_grepper_result_available()
        assert_msg = ("grepper couldn't match any line from the file " +
                      "(grep exit status was: {}).")
        assert_msg = assert_msg.format(self.last_grepper_result.exit_code)
        assert self.last_grepper_result, assert_msg

    def assert_grepper_linecount(self, linecount):
        """Assert the linecount of the last grepping result."""
        self._check_if_grepper_result_available()
        linecount = int(linecount)
        assert_msg = ("number of lines matched by the last grep command: {};" +
                      "expected: {}.")
        assert_msg = assert_msg.format(len(self.last_grepper_result),
                                       linecount)
        assert len(self.last_grepper_result) == linecount, assert_msg

    def get_last_result(self):
        """Return the last GrepperResult object given by the Grepper."""
        self._check_if_grepper_result_available()
        log_msg = "The last result is:\n{}"
        log_msg = log_msg.format(str(self.last_grepper_result))
        logging.info(log_msg)
        return self.last_grepper_result

    def get_last_result_output(self):
        """Return the output of the last grepping command."""
        self._check_if_grepper_result_available()
        log_msg = "Output of the last result is:\n{}"
        log_msg = log_msg.format(self.last_grepper_result.output)
        logging.info(log_msg)
        return self.last_grepper_result.output

    def get_last_result_errors(self):
        """Return the stderr output of the last grepping command."""
        self._check_if_grepper_result_available()
        log_msg = "Error output of the last result is:\n{}"
        log_msg = log_msg.format(self.last_grepper_result.errors)
        logging.info(log_msg)
        return self.last_grepper_result.errors

    def get_last_result_linecount(self):
        """Return the linecount of the last GrepperResult object."""
        self._check_if_grepper_result_available()
        log_msg = "Log count of the last result is: {}."
        log_msg = log_msg.format(len(self.last_grepper_result))
        logging.info(log_msg)
        return len(self.last_grepper_result)

    def get_last_result_exit_status(self):
        """Return the exit status from the last grep utility call."""
        self._check_if_grepper_result_available()
        log_msg = "Exit status of the last call was: {}."
        log_msg = log_msg.format(self.last_grepper_result.exit_code)
        logging.info(log_msg)
        return self.last_grepper_result.exit_code

    def _check_if_grepper_result_available(self):
        if self.last_grepper_result is None:
            exc_msg = "attempt to run grepper result keyword before grepping."
            raise RuntimeError(exc_msg)

    def _set_connection(self, connection):
        if not isinstance(connection, Connection):
            if connection is None:
                logging.info("Using default connection (no alias provided).")
            else:
                log_msg = "Using connection instance aliased as: {}."
                log_msg = log_msg.format(connection)
                logging.info(log_msg)
            connection = self.ssh.get_connection_by_alias(connection)
        else:
            logging.info("Using given connection instance.")
        self.grepper.connection = connection
        self.journal_reader.connection = connection

    def _run_grep(self, pattern, file_path, max_count, behavior):
        self.last_grepper_result = self.grepper.grep_file(pattern, file_path,
                                                          max_count=max_count,
                                                          behavior=behavior)
        return self.last_grepper_result

    def read_journal(self, current_boot=False, since=None, connection=None):
        """Read contents of systemd journal on the remote."""
        log_msg = "Reading journalctl contents {}"
        log_msg = log_msg.format("(only current boot)." if current_boot
                                 else ".")
        logging.info(log_msg)
        self._set_connection(connection)
        contents = self.journal_reader.read_journal(current_boot=current_boot)
        self.last_journalctl_contents = contents

    def get_last_journalctl_output(self):
        """Return the output of previously ran journalctl command."""
        self._check_if_journal_reader_result_available()
        log_msg = "Journalctl output:\n{}"
        log_msg = log_msg.format(self.last_journalctl_contents.output)
        logging.info(log_msg)
        return self.last_journalctl_contents.output

    def get_last_journalctl_errors(self):
        """Return errorout contents of previously ran journalctl command."""
        self._check_if_journal_reader_result_available()
        log_msg = "Journalctl error output:\n{}"
        log_msg = log_msg.format(self.last_journalctl_contents.output)
        logging.info(log_msg)
        return self.last_journalctl_contents.output

    def _check_if_journal_reader_result_available(self):
        if self.last_journalctl_contents is None:
            exc_msg = ("attempt to use journal reader result keyword " +
                       "before runnig it.")
            raise RuntimeError(exc_msg)
